using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
using UnityEngine.UI;
using UnityEngine.EventSystems;
namespace Titan {
    public class ScreenManager : MonoBehaviour {
        GameManager game;Canvas canvas;RectTransform root,body,modal;Text telemetry,status;Font font;PreviewFactory previews;readonly List<Button> buttons=new List<Button>();int dialogVersion;
        readonly Color ink=new Color(.035f,.07f,.11f,.94f),gold=new Color(.87f,.71f,.42f),teal=new Color(.43f,.72f,.73f);
        public void Initialize(GameManager g){game=g;previews=gameObject.AddComponent<PreviewFactory>();font=UnityEngine.Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");var go=new GameObject("Mission UI",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));canvas=go.GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;var scaler=go.GetComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1440,900);scaler.matchWidthOrHeight=.5f;root=go.GetComponent<RectTransform>();if(!EventSystem.current)new GameObject("UI navigation",typeof(EventSystem),typeof(StandaloneInputModule));}
        RectTransform Panel(Transform parent,string name,Vector2 min,Vector2 max,bool layout=true){var o=new GameObject(name,typeof(RectTransform),typeof(Image));o.transform.SetParent(parent,false);var r=o.GetComponent<RectTransform>();r.anchorMin=min;r.anchorMax=max;r.offsetMin=Vector2.zero;r.offsetMax=Vector2.zero;o.GetComponent<Image>().color=game.Save.preferences.highContrast?Color.black:ink;if(layout){var v=o.AddComponent<VerticalLayoutGroup>();v.padding=new RectOffset(16,16,12,12);v.spacing=8;v.childControlHeight=true;v.childForceExpandHeight=false;v.childControlWidth=true;v.childForceExpandWidth=true;}return r;}
        RectTransform ListPanel(string name,Vector2 min,Vector2 max){var outer=Panel(body,name,min,max,false);var scroll=outer.gameObject.AddComponent<ScrollRect>();var viewport=Panel(outer,"Viewport",Vector2.zero,Vector2.one,false);viewport.gameObject.AddComponent<RectMask2D>();var content=Panel(viewport,"Content",new Vector2(0,1),Vector2.one);content.pivot=new Vector2(.5f,1);content.gameObject.AddComponent<ContentSizeFitter>().verticalFit=ContentSizeFitter.FitMode.PreferredSize;scroll.viewport=viewport;scroll.content=content;scroll.horizontal=false;return content;}
        public Text Label(Transform parent,string value,int size=20,int height=44){var go=new GameObject(value,typeof(RectTransform),typeof(Text),typeof(LayoutElement));go.transform.SetParent(parent,false);var text=go.GetComponent<Text>();text.font=font;text.text=value;text.fontSize=size;text.color=Color.white;text.supportRichText=false;text.verticalOverflow=VerticalWrapMode.Truncate;go.GetComponent<LayoutElement>().preferredHeight=height;return text;}
        public Button Button(Transform parent,string title,Action action,int height=62){var go=new GameObject(title,typeof(RectTransform),typeof(Image),typeof(Button),typeof(LayoutElement));go.transform.SetParent(parent,false);go.GetComponent<LayoutElement>().preferredHeight=height;go.GetComponent<Image>().color=game.Save.preferences.colorBlind?new Color(.28f,.45f,.7f):new Color(.16f,.29f,.31f);var b=go.GetComponent<Button>();b.onClick.AddListener(()=>{game.Audio.Beep(520);action();});var txt=Label(go.transform,title,18,height);var r=txt.rectTransform;r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=new Vector2(12,4);r.offsetMax=new Vector2(-12,-4);txt.alignment=TextAnchor.MiddleLeft;buttons.Add(b);return b;}
        public void Rebuild(){buttons.Clear();if(body){body.gameObject.SetActive(false);Destroy(body.gameObject);}body=Panel(root,"Screen",Vector2.zero,Vector2.one,false);body.GetComponent<Image>().color=Color.clear;body.GetComponent<Image>().raycastTarget=false;
            var top=Panel(body,"Dashboard",new Vector2(.02f,.86f),new Vector2(.98f,.98f));Label(top,"TITAN: DEEP FRONTIER  /  "+game.Screen.ToString().ToUpper(),22,30);if(game.Screen==Stage.Build||game.Screen==Stage.Validate){var hud=new GameObject("Resource dashboard",typeof(RectTransform));hud.transform.SetParent(top,false);hud.AddComponent<ResourceHUD>().Initialize(game,font);telemetry=null;}else telemetry=Label(top,"",18,42);
            var foot=Panel(body,"Instructions",new Vector2(.02f,.015f),new Vector2(.98f,.15f));status=Label(foot,"",18,50);var menu=new GameObject("Menu",typeof(RectTransform),typeof(HorizontalLayoutGroup),typeof(LayoutElement));menu.transform.SetParent(foot,false);menu.GetComponent<LayoutElement>().preferredHeight=44;menu.GetComponent<HorizontalLayoutGroup>().spacing=12;Button(menu.transform,"Home",()=>game.Go(Stage.Title),44);Button(menu.transform,"Settings / Pause",Settings,44);Button(menu.transform,"NASA science lab",Gallery,44);
            var left=ListPanel("Mission controls",new Vector2(.02f,.18f),new Vector2(game.Screen==Stage.Build?.24f:.38f,.84f));var m=game.Mission;
            switch(game.Screen){
                case Stage.Title:Label(left,"Big wonders. Little explorer.",32,90);Label(left,"A 3D mission with Pip.\nFictional mission, real scientific inspiration. This game is not a NASA product.",18,100);Button(left,"Start your mission →",()=>game.New(false));if(game.Save.mission!=null)Button(left,"Continue",game.Continue);Button(left,"Advanced spacecraft workshop ↗",()=>game.New(true));Label(left,"BUILD → LAUNCH → TRAVEL → LAND → DISCOVER",16,65);break;
                case Stage.Destination:
                    Label(left,"Choose your destination",26,60);foreach(var d in game.Data.destinations){var destination=d;Picture(left,previews.Get(d.id,true),120);Button(left,(m.destination==d.id?"✓ ":"")+d.name+"\n"+d.description,()=>{m.destination=destination.id;game.Persist();game.View.Rebuild();Rebuild();},100);Label(left,$"Gravity {d.gravity} m/s² · "+(d.id=="titan"?"Gentle guided splashdown":d.id=="mars"?"Tricky: thin-air landing":"Careful: powered descent"),16,48);}if(m.advanced)for(int i=0;i<game.Data.difficulties.Length;i++){int n=i;Button(left,game.Data.difficulties[i].name+" — "+game.Data.difficulties[i].budget+" MC",()=>{m.difficulty=n;game.Persist();Rebuild();});}Button(left,"Build for "+game.Data.World(m.destination).name+" →",()=>game.Go(Stage.Build));break;
                case Stage.Build:
                    Label(left,"Make Pip yours",26,50);foreach(Category cat in Enum.GetValues(typeof(Category))){var selected=cat;Button(left,(game.Category==cat?"● ":"")+cat,()=>{game.Category=selected;game.View.Rebuild();Rebuild();});}
                    Button(left,"Previous",()=>game.ChangeCategory(-1));Button(left,"Next",()=>game.ChangeCategory(1));Button(left,"Check my spacecraft →",()=>game.Go(Stage.Validate));Label(left,"Drag the open scene to orbit.\nAll equipment numbers are fictional game values.",16,85);
                    var right=ListPanel("Part cards",new Vector2(.72f,.18f),new Vector2(.98f,.84f));foreach(var p in game.Data.parts.Where(p=>p.category==game.Category)){var part=p;bool chosen=m.design.rocket==p.id||m.design.power==p.id||m.design.radio==p.id||m.design.science.Contains(p.id);Picture(right,previews.Get(p.id),130);Button(right,(chosen?"✓ ":"+ ")+p.name+"\n"+(p.category==Category.Rockets?"":p.mass+" kg · ")+p.cost+" MC\n"+(p.category==Category.Rockets?p.capacity+" kg capacity":p.category==Category.Power?p.generation+" W · "+p.battery+" Wh":p.draw+" W · "+(p.category==Category.Radio?p.rate+" units/hr":p.points+" science")),()=>game.Select(part.id),112);Label(right,p.description,16,75);}break;
                case Stage.Validate:
                    var errors=MissionEngine.Validate(m,game.Data);Label(left,errors.Count==0?"Ready for the extraordinary!":"A few little fixes",27,70);foreach(var error in errors)Label(left,error,18,85);if(errors.Count==0){Label(left,"Navigation, insulation, heat protection and destination landing gear are included in your core. Run science one tool at a time when demand exceeds generation.",18,145);Button(left,"Let's launch →",game.BeginLaunch);}Button(left,"Back to building",()=>game.Go(Stage.Build));break;
                case Stage.Launch:Label(left,"Hold to lift off",28,60);Hold(left,"Hold Space / hold here to launch",()=>game.Held=true,()=>game.Held=false);Button(left,"Edit spacecraft",()=>{if(game.Progress==0)game.Go(Stage.Build);});break;
                case Stage.Travel:
                    Label(left,"Fly through three rings",26,65);Label(left,"Steer with arrows or WASD. Hold Space or Fly to move forward. Release to pause travel.",18,95);Hold(left,"Hold to fly",()=>game.Held=true,()=>game.Held=false);Directions(left);
                    if(m.advanced){Button(left,"Course correction (5 kg fuel)",()=>game.CorrectCourse());Button(left,m.destination=="titan"?"Saturn flyby / recharge":"Coast / recharge",game.Recharge);}break;
                case Stage.Land:
                    Label(left,game.Data.World(m.destination).name+" arrival",26,65);Label(left,m.destination=="moon"?"No parachute here! Enable retro-rockets before advancing descent.":"Advance at your pace. Deploy a parachute once dynamic pressure is safe.",18,115);Button(left,"Advance descent",game.Descend);if(m.destination!="moon")Button(left,m.chute?"✓ Parachute open":"Deploy parachute",()=>{if(MissionEngine.Deploy(m,game.Data.World(m.destination)))game.Audio.Beep(220,.3f);game.Persist();Rebuild();});if(m.destination!="titan")Button(left,m.retro?"✓ Retro-rockets on":"Enable retro-rockets",()=>{m.retro=true;game.Persist();Rebuild();});if(m.advanced){Button(left,"Stabilize attitude (5 kg fuel)",game.CorrectCourse);if(m.destination=="titan")Button(left,"Steep approach (more heating)",()=>{if(m.altitude>80000){m.speed=5200;m.feedback="Steep entry selected. Higher speed increases heating cubically.";game.Persist();}else m.feedback="Entry is already underway. Approach changes are locked.";});}Directions(left);break;
                case Stage.Explore:
                    Label(left,"Find five little wonders",26,65);Label(left,"Move with WASD or arrows. Get close to a glowing marker and collect. No real-time energy countdown.",18,100);Button(left,"Collect nearby discovery",game.Collect);Directions(left);Label(left,"LAKE / SURFACE MAP",18,35);var map=new GameObject("Exploration map",typeof(RectTransform));map.transform.SetParent(left,false);map.AddComponent<ExplorationMap>().Initialize(game);for(int i=0;i<5;i++){int n=i;Button(left,(m.found.Contains(i)?"✓ ":"○ ")+game.Data.World(m.destination).facts[i].title,()=>game.GuideTo(n),48);}Button(left,"Recharge battery",game.Recharge);if(m.found.Count==5)Button(left,"Send discoveries home →",()=>game.Go(Stage.Transmit));break;
                case Stage.Transmit:Label(left,"Send a hello to Earth",27,60);Label(left,"Radio choice affects mission hours and energy used. Transmission is an untimed decision.",18,100);Button(left,"Transmit discoveries",game.Transmit);Button(left,"Recharge first",game.Recharge);break;
                case Stage.Results:Label(left,m.failed?"Every journey teaches us something":"You are a space explorer!",28,90);Label(left,"Score: "+m.score+" / 100\nDiscoveries: "+m.found.Count+" / 5\nData home: "+m.sent+" units\nIntegrity: "+m.integrity.ToString("F0")+"%",22,145);if(m.transmitted)Label(left,"★ Space pilot\n★ Surface explorer\n★ Science buddy",22,100);Label(left,"Score: science 50 + transmission 25 + integrity 15 + savings up to 10.",16,85);Button(left,"Refine my spacecraft →",game.Refine);Button(left,"New adventure",()=>game.New(m.advanced));break;
            }UpdateHUD();Publish();
        }
        void Hold(Transform p,string text,Action down,Action up){var b=Button(p,text,()=>{});var hold=b.gameObject.AddComponent<HoldButton>();hold.down=down;hold.up=up;}
        void Directions(Transform p){foreach(var dir in new[]{Vector2.up,Vector2.left,Vector2.down,Vector2.right}){var d=dir;Hold(p,d==Vector2.up?"↑ Move up":d==Vector2.down?"↓ Move down":d==Vector2.left?"← Move left":"→ Move right",()=>game.Touch=d,()=>game.Touch=Vector2.zero);}}
        public void UpdateHUD(){var m=game.Mission;if(telemetry)telemetry.text=$"{game.Data.World(m.destination).name}     Battery {m.battery:0} Wh    Fuel {m.fuel:0} kg    Integrity {m.integrity:0}%    Altitude {m.altitude:0} m    Rings {m.rings}/3";if(status)status.text=m.feedback;}
        void Picture(Transform parent,Texture texture,int height){if(!texture)return;var o=new GameObject("Picture",typeof(RectTransform),typeof(RawImage),typeof(LayoutElement));o.transform.SetParent(parent,false);o.GetComponent<RawImage>().texture=texture;o.GetComponent<LayoutElement>().preferredHeight=height;}
        void Publish(){if(buttons.Count>0)EventSystem.current.SetSelectedGameObject(buttons[0].gameObject);AccessibilityBridge.Publish(buttons.Where(b=>b).Select(b=>b.GetComponentInChildren<Text>().text).ToArray(),string.Join(". ",(modal?modal:body).GetComponentsInChildren<Text>().Select(t=>t.text)));}
        public void Dialog(string title,string message,string link=null){dialogVersion++;game.Paused=true;game.Held=false;game.Touch=Vector2.zero;buttons.Clear();var shade=Panel(body,"Modal shield",Vector2.zero,Vector2.one,false);shade.GetComponent<Image>().color=new Color(0,0,0,.65f);modal=ListPanel("Dialog",new Vector2(.22f,.18f),new Vector2(.78f,.84f));Label(modal,title,27,70);if(!string.IsNullOrEmpty(message))Label(modal,message,20,Mathf.Max(90,Mathf.CeilToInt(message.Length/48f)*28));if(link!=null)Button(modal,"Read the NASA reference ↗",()=>Application.OpenURL(link));Button(modal,"Continue →",Close);Publish();}
        public void Close(){dialogVersion++;game.Paused=false;game.Held=false;game.Touch=Vector2.zero;modal=null;Rebuild();}
        public void PauseMenu(){if(!game.Paused)Settings();}
        void Settings(){Dialog("Take a little breather","Your mission is paused. Changes save on this device.");Button(modal,"Sound: "+game.Save.preferences.sound,()=>{game.Save.preferences.sound=!game.Save.preferences.sound;game.Persist();Close();Settings();});Button(modal,"Reduced motion: "+game.Save.preferences.reducedMotion,()=>{game.Save.preferences.reducedMotion=!game.Save.preferences.reducedMotion;game.View.Rebuild();game.Persist();Close();});Button(modal,"High contrast: "+game.Save.preferences.highContrast,()=>{game.Save.preferences.highContrast=!game.Save.preferences.highContrast;game.Persist();Close();});Button(modal,"Color-blind palette: "+game.Save.preferences.colorBlind,()=>{game.Save.preferences.colorBlind=!game.Save.preferences.colorBlind;game.Persist();Close();});Publish();}
        void Gallery(){Dialog("NASA science lab","Loading real NASA imagery…\nGame artwork is separate from NASA imagery.");int version=dialogVersion;string destination=game.Mission.destination;game.StartCoroutine(game.Nasa.Images(destination,result=>{if(!modal||version!=dialogVersion)return;foreach(Transform child in modal){child.gameObject.SetActive(false);Destroy(child.gameObject);}buttons.Clear();Label(modal,"NASA imagery · "+result.status,24,65);foreach(var item in result.items.Take(3)){var entry=item;if(item.texture)Picture(modal,item.texture,220);Button(modal,item.title+"\n"+item.credit,()=>Application.OpenURL(entry.url),110);}Label(modal,result.message,16,100);var pds=Label(modal,"Checking PDS records…",16,170);game.StartCoroutine(game.Nasa.Datasets(destination,text=>{if(pds&&version==dialogVersion){pds.text=text;Publish();}}));Button(modal,"PDS data catalogue ↗",()=>Application.OpenURL("https://pds.nasa.gov/datasearch/data-search/"));Button(modal,"Close",Close);Publish();}));}
        void Update(){UpdateHUD();if(Input.GetKeyDown(KeyCode.Tab)&&buttons.Count>0){int index=buttons.FindIndex(b=>b&&b.gameObject==EventSystem.current.currentSelectedGameObject);for(int n=1;n<=buttons.Count;n++){var b=buttons[(index+n)%buttons.Count];if(b&&b.IsActive()&&b.interactable){EventSystem.current.SetSelectedGameObject(b.gameObject);break;}}}}
        public void Activate(int i){if(i>=0&&i<buttons.Count&&buttons[i]&&buttons[i].interactable){var hold=buttons[i].GetComponent<HoldButton>();if(hold)hold.Toggle();else buttons[i].onClick.Invoke();}}
    }
    public class HoldButton:MonoBehaviour,IPointerDownHandler,IPointerUpHandler,IPointerExitHandler {public Action down,up;bool latched;public void Toggle(){latched=!latched;if(latched)down?.Invoke();else up?.Invoke();}public void OnPointerDown(PointerEventData e)=>down?.Invoke();public void OnPointerUp(PointerEventData e)=>up?.Invoke();public void OnPointerExit(PointerEventData e)=>up?.Invoke();void OnDisable()=>up?.Invoke();}
}
